head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 메뉴 관리 화면 진입점 — 결과 보관용 scwin.res를 초기화하고 메뉴 목록 초기 조회를 수행한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
    try {

        scwin.res = {};
        scwin.select_list_call();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT_N003.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
