 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sel_lvlCd_onchange(info);
 */
scwin.sel_lvlCd_onchange = function (info) {
    try {
        scwin.select_list_call();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT_N003.sel_lvlCd_onchange" });
    }
};

