/**
 * @method
 * @name btn_newInsert_onclick
 * @description 신규 등록 버튼 클릭 — 임시 생성한 메뉴ID(temp_getValue)를 전달해 메뉴 등록 팝업(ULDMGT_N004)을 열고, 종료 결과를 btn_newInsertCallback으로 전달한다.
 * @returns {void}
 * @hidden N
 * @example scwin.btn_newInsert_onclick();
 */
scwin.btn_newInsert_onclick = async function () {
    try {
        const data = { type: "confirm", msg: scwin.temp_getValue() , rdo:rdo_system.getValue()}; // 임시로 생성한 번호임 수정필요
        const options = {
            id: "ConfirmPop",
            title: "Confirm_Pop",
            width:"920px",
            height: "470px"
        };
        const result = await $c.win.openPopup("/ui/mgt/ULDMGT_N004.xml", options, data);
        scwin.btn_newInsertCallback(result);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT_N003.btn_newInsert_onclick" });
    }
};

/**
 * @method
 * @name grd_menu_oncellclick
 * @description 메뉴 그리드(grd_menu) 셀 클릭 이벤트 — 수정 컬럼(9) 클릭 시 메뉴 수정 팝업(ULDMGT_N002)을 열고, 삭제 컬럼(10) 클릭 시 확인 후 메뉴 삭제(sbm_delete)를 실행한다.
 * @param {Number} rowIndex 클릭한 행 인덱스
 * @param {Number} columnIndex 클릭한 컬럼 인덱스
 * @param {String} columnId 클릭한 컬럼 ID
 * @returns {void}
 * @hidden N
 * @example scwin.grd_menu_oncellclick(rowIndex, columnIndex, columnId);
 */
scwin.grd_menu_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        console.log ("columnIndex :" + columnIndex + " rowIndex:"+ rowIndex+ "  columnId:"+ columnId);
        if(columnIndex === 9)
        {
            const data = { type: "confirm", jval: dlt_select_list_content.getRowJSON(rowIndex),  callBackParam:"scwin.grd_menuUpdateCallback" };
            const options = {
                id: "ConfirmPop",
                title: "Confirm_Pop",
                width:"920px",
                height: "470px"
            };

            const result = await $c.win.openPopup("/ui/mgt/ULDMGT_N002.xml", options, data);
            scwin.grd_menuUpdateCallback(result);
        };
        if(columnIndex === 10)
        {
            const rmenuId = dlt_select_list_content.getCellData(rowIndex, "menuId");
            const rmenuNm = dlt_select_list_content.getCellData(rowIndex, "menuNm");
            const vmsg = "메뉴 "+ rmenuNm +"(" + rmenuId + ") 을(를) 삭제하시겠습니까?";

            if (await $c.win.confirm(vmsg))
            {
                dma_delete.set("menuId", rmenuId);
                scwin.res = await $c.sbm.execute(sbm_delete,  dma_delete.getJSON());
                if (scwin.res.responseJSON.success === true) {
                    scwin.res.saveFlag = "delete";
                    $c.win.closePopup(scwin.res);
                    scwin.grd_menuDelCallback(scwin.res);

                }
            } else {
                $c.win.closePopup();
            }

        };
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT_N003.grd_menu_oncellclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name sbm_select_list_submitdone
 * @description 메뉴 목록 조회(sbm_select_list) 완료 콜백 — 조회 건수를 표시하고 결과를 dlt_select_list_content에 반영한다.
 * @param {Object} e 서브미션 완료 이벤트/결과 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbm_select_list_submitdone(e);
 */
scwin.sbm_select_list_submitdone = function (e) {
    const result = e.responseJSON;

    if(result.success) {
        const obj = result.body;

        console.log("cnt : "+ obj.length);
        textbox_1.setValue (obj.length);

        dlt_select_list_content.setJSON(obj);
    }
    else{
        $c.win.alert(result.message);
    }
};

/**
 * @method
 * @name btn_newInsertCallback
 * @description confirm에 대한 callback 함수, 부모창으로 파라미터를 전송한다. (메뉴 등록 팝업 종료 결과 수신)
 * @param {String|Number} arg 부모창으로 전달할 값
 * @returns {void}
 * @hidden N
 * @example scwin.btn_newInsertCallback(arg);
 */
scwin.btn_newInsertCallback = function (arg) {

    console.log ("btn_newInsertCallback :" + arg);
};

/**
 * @method
 * @name sbm_delete_submitdone
 * @description 메뉴 삭제(sbm_delete) 완료 콜백 — 성공 시 메뉴 목록을 재조회하고, 실패 시 오류 메시지를 표시한다.
 * @param {Object} e 서브미션 완료 이벤트/결과 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbm_delete_submitdone(e);
 */
scwin.sbm_delete_submitdone = function (e) {
    const result = e.responseJSON;

    if(result.success) {

        console.log ("success? : true");
        scwin.select_list_call();
    }
    else{
        $c.win.alert(result.message);
    }
};

/**
 * @method
 * @name grd_menuUpdateCallback
 * @description 메뉴 수정 팝업 종료 콜백 — 전달받은 결과를 로그로 출력한다.
 * @param {String|Number|Object} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 * @example scwin.grd_menuUpdateCallback(arg);
 */
scwin.grd_menuUpdateCallback = function ( arg ){
    console.log ("grd_menuUpdateCallback :" + arg);
};

/**
 * @method
 * @name grd_menuDelCallback
 * @description 메뉴 삭제 처리 콜백 — 전달받은 결과를 로그로 출력한다.
 * @param {String|Number|Object} arg 삭제 처리 결과 값
 * @returns {void}
 * @hidden N
 * @example scwin.grd_menuDelCallback(arg);
 */
scwin.grd_menuDelCallback = function ( arg ){
    console.log ("grd_menuDelCallback? :" + arg);
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name select_list_call
 * @description 초기 조회 — 검색 조건(시스템 구분/메뉴명/Depth/사용여부)으로 dma_select_list를 구성해 sbm_select_list를 실행한다.
 * @returns {void}
 * @hidden N
 * @example scwin.select_list_call();
 */
scwin.select_list_call = function() {
    console.log("rdo : "+ rdo_system.getValue());
    console.log("menuNm : "+ ipt_menuNm.getValue());
    console.log("lvlCd : "+ sel_lvlCd.getValue());
    console.log("useYn : "+ sel_useYn.getValue());

    dma_select_list.set("notiObjSysTpCd", rdo_system.getValue());
    dma_select_list.set("menuNm", ipt_menuNm.getValue());
    dma_select_list.set("lvlCd",   sel_lvlCd.getValue());
    dma_select_list.set("useYn", sel_useYn.getValue());

    $c.sbm.execute(sbm_select_list, dma_select_list.getJSON());
};

/**
 * @method
 * @name random3Digital
 * @description 100~999 범위의 3자리 난수를 생성한다.
 * @returns {Number} 3자리 난수
 * @hidden N
 * @example scwin.random3Digital();
 */
scwin.random3Digital = function(){
    return Math.floor(Math.random() * 900) + 100;
};

/**
 * @method
 * @name temp_getValue
 * @description 신규 등록용 임시 메뉴ID를 생성한다(현재는 고정값 "STF15920" 반환).
 * @returns {String} 임시 메뉴ID
 * @hidden N
 * @example scwin.temp_getValue();
 */
scwin.temp_getValue = function()
{
    let imsival = "";
    const imsi = dlt_select_list_content.getCellData(0, "menuId");
    const num = scwin.random3Digital();

    if(imsi.length > 3)
    {
        imsival = imsi.substring(0, 3) + "-" + num;
    }else{
        imsival = "000" + "-" + num;
    }

    imsival = "STF15920";
    return imsival;
};
